        vm.assume(t > 0 && t < 2**64);
        address actor = address(0xABCD);
        vm.deal(actor, 20 ether);

        vm.warp(t);
        vm.prank(actor);
        c.fallback{value: 10 ether}();
        uint256 afterFirst = c.pastBlockTime();

        // second call in the SAME block timestamp: guard demands t > pastBlockTime,
        // which fails here in the reference, so it reverts; the mutant succeeds.
        vm.prank(actor);
        bool ok;
        try c.fallback{value: 10 ether}() { ok = true; } catch { ok = false; }

        // General rule: a second same-timestamp call must revert (guard enforces
        // strictly increasing timestamps), so pastBlockTime stays at afterFirst.
        assertTrue(ok == false && c.pastBlockTime() == afterFirst);
    }
}

