// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reverter r;

    function setUp() public { c = new C{value: 10 ether}(); r = new Reverter(); }

    function testFuzz_property(uint256 t, uint256 n) public {
        vm.assume(t < type(uint256).max - 1);
        // force the payout branch: block.number % 15 == 0
        vm.roll(block.number - (block.number % 15));
        vm.warp(t);
        vm.deal(address(r), 10 ether);
        // msg.sender of the fallback is the reverting helper, so the internal
        // transfer inside the payout branch reverts; catch it low-level.
        r.ping(payable(address(c)));
        // Rule: pastBlockTime is always updated to call time + 1, even when
        // the payout transfer reverted.
        assertTrue(c.pastBlockTime() == t + 1);
    }
}

contract Reverter {
    // has no receive/payable fallback that accepts ETH -> transfers to it revert
    fallback() external payable {
        revert();
    }

    function ping(address payable target) external {
        (bool ok, ) = target.call{value: 10 ether}("");
        ok; // swallow the revert of the inner call
    }
}
